125|@Composable
126|fun MetroApp() {
127| val navController = rememberNavController()
128| val context = LocalContext.current
129|
130| // Cargar datos del JSON
131| val metroData = remember {
132| try {
133| val jsonString =
134| context.assets.open("metro_madrid.json").bufferedReader().use { it.readText() }
135| Json.decodeFromString<MetroData>(jsonString)
136| } catch (e: IOException) {
137| // Datos de ejemplo para preview
138| MetroData(
139| lineas = listOf(
140| Linea(
141| nombre = "linea-1",
142| estaciones = listOf(
143| Estacion(
144| nombre = "Pinar de Chamartín",
145| incidencias_generales = "",
146| correspondencias = emptyList(),
147| incidencias_especificas = emptyList(),
148| tiene_incidencias = false
149| ),
150| Estacion(
151| nombre = "Bambú",
152| incidencias_generales = "Escaleras mecánicas fuera de servicio",
153| correspondencias = emptyList(),
154| incidencias_especificas = listOf(
155| IncidenciaEspecifica(
156| tipo = "Escaleras mecánicas",
157| imagen = "",
158| descripcion = "Fuera de servicio por trabajos de mejora"
159| )
160| ),
161| tiene_incidencias = true
162| )
163| )
164| )
165| )
166| )
167| }
168| }
169|
170| NavHost(
171| navController = navController,
172| startDestination = "lineas"
173| ) {
174| composable("lineas") {
175| LineasScreen(
176| lineas = metroData.lineas,
177| onLineaClick = { linea ->
178| navController.navigate("estaciones/${linea.nombre}")
179| }
180| )
181| }
182|
183| composable("estaciones/{lineaNombre}") { backStackEntry ->
184| val lineaNombre = backStackEntry.arguments?.getString("lineaNombre")
185| val linea = metroData.lineas.find { it.nombre == lineaNombre }
186|
187| if (linea != null) {
188| EstacionesScreen(
189| linea = linea,
190| onBackClick = { navController.popBackStack() }
191| )
192| }
193| }
194| }
