231|@Composable
232|fun LineaCard(
233| linea: Linea,
234| onClick: () -> Unit
235|) {
236| val estacionesConIncidencias = linea.estaciones.count { it.tiene_incidencias }
237|
238| Card(
239| modifier = Modifier
240| .fillMaxWidth()
241| .clickable { onClick() },
242| elevation = CardDefaults.cardElevation(defaultElevation = 4.dp),
243| colors = CardDefaults.cardColors(
244| containerColor = if (estacionesConIncidencias > 0)
245| Color(0xFFFFEBEE) else Color.White
246| )
247| ) {
248| Row(
249| modifier = Modifier
250| .fillMaxWidth()
251| .padding(16.dp),
252| horizontalArrangement = Arrangement.SpaceBetween,
253| verticalAlignment = Alignment.CenterVertically
254| ) {
255| Column {
256| Text(
257| text = formatLineaName(linea.nombre),
258| fontSize = 18.sp,
259| fontWeight = FontWeight.Bold
260| )
261| Text(
262| text = "${linea.estaciones.size} estaciones",
263| fontSize = 14.sp,
264| color = Color.Gray
265| )
266| if (estacionesConIncidencias > 0) {
267| Text(
268| text = "$estacionesConIncidencias con incidencias",
269| fontSize = 12.sp,
270| color = Color(0xFFD32F2F)
271| )
272| }
273| }
274|
275| Icon(
276| imageVector = Icons.AutoMirrored.Filled.ArrowForward,
277| contentDescription = "Ver estaciones",
278| tint = MaterialTheme.colorScheme.primary
279| )
280| }
281| }
