284|@OptIn(ExperimentalMaterial3Api::class)
285|@Composable
286|fun EstacionesScreen(
287| linea: Linea,
288| onBackClick: () -> Unit
289|) {
290| var searchQuery by remember { mutableStateOf(TextFieldValue("")) }
291| var showOnlyIncidencias by remember { mutableStateOf(false) }
292|
293| val filteredEstaciones = remember(searchQuery.text, showOnlyIncidencias) {
294| derivedStateOf {
295| linea.estaciones.filter { estacion ->
296| val matchesSearch = estacion.nombre.contains(searchQuery.text, ignoreCase = true)
297| val matchesFilter = !showOnlyIncidencias || estacion.tiene_incidencias
298| matchesSearch && matchesFilter
299| }
300| }
301| }
302|
303| Scaffold(
304| topBar = {
305| TopAppBar(
306| title = { Text(formatLineaName(linea.nombre)) },
307| navigationIcon = {
308| IconButton(onClick = onBackClick) {
309| Icon(
310| imageVector = Icons.AutoMirrored.Filled.ArrowBack,
311| contentDescription = "Volver",
312| tint = Color.White
313| )
314| }
315| },
316| colors = TopAppBarDefaults.topAppBarColors(
317| containerColor = MaterialTheme.colorScheme.primary,
318| titleContentColor = Color.White
319| )
320| )
321| }
322| ) { paddingValues ->
323| Column(
324| modifier = Modifier
325| .fillMaxSize()
326| .padding(paddingValues)
327| ) {
328| // Search and Filter Section
329| Column(
330| modifier = Modifier
331| .fillMaxWidth()
332| .padding(16.dp)
333| ) {
334| TextField(
335| value = searchQuery,
336| onValueChange = { searchQuery = it },
337| modifier = Modifier
338| .fillMaxWidth()
339| .padding(bottom = 8.dp),
340| placeholder = { Text("Buscar estación...") },
341| singleLine = true,
342| colors = TextFieldDefaults.colors(
343| focusedContainerColor = MaterialTheme.colorScheme.surface,
344| unfocusedContainerColor = MaterialTheme.colorScheme.surface
345| )
346| )
347|
348| Row(
349| modifier = Modifier.fillMaxWidth(),
350| horizontalArrangement = Arrangement.SpaceBetween,
351| verticalAlignment = Alignment.CenterVertically
352| ) {
353| Text(
354| text = "Mostrar solo estaciones con incidencias",
355| fontSize = 14.sp
356| )
357| Switch(
358| checked = showOnlyIncidencias,
359| onCheckedChange = { showOnlyIncidencias = it }
360| )
361| }
362| }
363|
364| // Stations List
365| LazyColumn(
366| modifier = Modifier
367| .fillMaxSize()
368| .padding(horizontal = 16.dp),
369| verticalArrangement = Arrangement.spacedBy(8.dp)
370| ) {
371| items(filteredEstaciones.value) { estacion ->
372| EstacionCard(estacion = estacion,modifier = Modifier.animateItem())
373| }
374| }
375| }
376| }
377|}
