379|@Composable
380|fun EstacionCard(estacion: Estacion, modifier: Modifier) {
381| var expanded by remember { mutableStateOf(false) }
382| val hasExpandableContent = estacion.correspondencias.isNotEmpty() || estacion.incidencias_especificas.isNotEmpty()
383|
