388| containerColor = if (estacion.tiene_incidencias)
389| Color(0xFFFFCDD2) else Color.White
390| )
391| ) {
392| Column {
393| Row(
394| modifier = Modifier
395| .fillMaxWidth()
396| .then(
397| if (hasExpandableContent) {
398| Modifier.clickable { expanded = !expanded }
399| } else {
400| Modifier
401| }
402| )
403| .padding(16.dp),
404| horizontalArrangement = Arrangement.SpaceBetween,
405| verticalAlignment = Alignment.CenterVertically
406| ) {
407| Row(
408| verticalAlignment = Alignment.CenterVertically
409| ) {
410| if (estacion.tiene_incidencias) {
411| Icon(
412| imageVector = Icons.Default.Warning,
413| contentDescription = "Incidencias",
414| tint = Color(0xFFD32F2F),
415| modifier = Modifier.size(20.dp)
416| )
417| Spacer(modifier = Modifier.width(8.dp))
418| }
419|
420| Text(
421| text = estacion.nombre,
422| fontSize = 16.sp,
423| fontWeight = FontWeight.Medium
424| )
425|
426| AnimatedVisibility(
427| visible = !expanded,
428| enter = expandIn(expandFrom = Alignment.Center),
429| exit = shrinkOut(shrinkTowards = Alignment.Center)
430| ) {
431| // if (!expanded) {
432| Row {
433| estacion.incidencias_especificas.map { it.imagen }.forEach {
434| val (resourceId, description) = getImageDrawableResource(it)
435| Image(
436| painter = painterResource(resourceId),
437| contentDescription = description,
438| modifier = Modifier
439| .size(40.dp)
440| .padding(6.dp)
441| )
442| }
443| }
444| }
445| }
446|
447| if (hasExpandableContent) {
448| Icon(
449| imageVector = if (expanded) Icons.Default.ExpandLess else Icons.Default.ExpandMore,
450| contentDescription = if (expanded) "Contraer" else "Expandir"
451| )
452| }
453| }
454|
455| AnimatedVisibility(
456| visible = expanded && hasExpandableContent,
457| enter = fadeIn(animationSpec = tween(300)) + expandVertically(
458| animationSpec = tween(300)
459| ),
460| exit = fadeOut(animationSpec = tween(300)) + shrinkVertically(
461| animationSpec = tween(300)
462| )
463| ) {
464| Column(
465| modifier = Modifier.padding(start = 16.dp, end = 16.dp, bottom = 16.dp)
466| ) {
467| HorizontalDivider(modifier = Modifier.padding(bottom = 12.dp))
468|
469| // Correspondencias
470| if (estacion.correspondencias.isNotEmpty()) {
471| Text(
472| text = "Correspondencias:",
473| fontWeight = FontWeight.Medium,
474| fontSize = 14.sp
475| )
476| Text(
477| text = "${estacion.correspondencias.size} líneas",
478| fontSize = 12.sp,
479| color = Color.Gray,
480| modifier = Modifier.padding(bottom = 4.dp)
481| )
482|
483| FlowRow(
484| horizontalArrangement = Arrangement.spacedBy(8.dp),
485| verticalArrangement = Arrangement.spacedBy(8.dp),
486| maxItemsInEachRow = 5,
487| modifier = Modifier.padding(bottom = 8.dp)
488| ) {
489| estacion.correspondencias.forEach { svgUrl ->
490| val (resourceId, description) = getImageDrawableResource(svgUrl)
491| Image(
492| painter = painterResource(resourceId),
493| contentDescription = description,
494| modifier = Modifier
495| .size(40.dp)
496| .padding(6.dp)
497| )
498| }
499| }
500| }
501|
502| // Incidencias específicas
503| estacion.incidencias_especificas.forEach { incidencia ->
504| Card(
505| modifier = Modifier
506| .fillMaxWidth()
507| .padding(vertical = 4.dp),
508| colors = CardDefaults.cardColors(
509| containerColor = Color(0xFFFFF3E0)
510| )
511| ) {
512| Column(
513| modifier = Modifier.padding(12.dp)
514| ) {
515| Row(verticalAlignment = Alignment.CenterVertically) {
516| Text(
517| text = incidencia.tipo,
518| fontWeight = FontWeight.Medium,
519| fontSize = 13.sp,
520| color = Color(0xFFE65100)
