548|@Composable
549|fun formatLineaName(nombre: String): String {
550| return when {
551| nombre.startsWith("linea-") -> "Línea ${nombre.removePrefix("linea-").uppercase()}"
552| nombre.startsWith("ml") -> "Metro Ligero ${nombre.removePrefix("ml").uppercase()}"
553| nombre == "ramal" -> "Ramal"
554| else -> nombre.replaceFirstChar { it.uppercase() }
555| }
556|}
557|
558|fun getImageDrawableResource(svgUrl: String): Pair<Int, String> {
559| // Extract filename from URL
560| val fileName = svgUrl.substringAfterLast("/").removeSuffix(".svg")
561| 
562| return when {
563| fileName.startsWith("linea-") -> {
564| val numero = fileName.removePrefix("linea-")
565| when (numero) {
566| "1" -> Pair(R.drawable.linea_1, "Línea 1")
567| "2" -> Pair(R.drawable.linea_2, "Línea 2")
568| "3" -> Pair(R.drawable.linea_3, "Línea 3")
569| "4" -> Pair(R.drawable.linea_4, "Línea 4")
570| "5" -> Pair(R.drawable.linea_5, "Línea 5")
571| "6" -> Pair(R.drawable.linea_6_circular, "Línea 6 Circular")
572| "7" -> Pair(R.drawable.linea_7, "Línea 7")
573| "8" -> Pair(R.drawable.linea_8, "Línea 8")
574| "9" -> Pair(R.drawable.linea_9, "Línea 9")
575| "10" -> Pair(R.drawable.linea_10, "Línea 10")
576| "11" -> Pair(R.drawable.linea_11, "Línea 11")
577| "12" -> Pair(R.drawable.linea_12_metrosur, "Línea 12 MetroSur")
578| else -> Pair(R.drawable.linea_1, "Línea 1") // Default fallback
579| }
580| }
581| fileName.startsWith("ml") -> {
582| val numero = fileName.removePrefix("ml")
583| when (numero) {
584| "1" -> Pair(R.drawable.ml1, "Metro Ligero 1")
585| "2" -> Pair(R.drawable.ml2, "Metro Ligero 2")
586| "3" -> Pair(R.drawable.ml3, "Metro Ligero 3")
587| else -> Pair(R.drawable.ml1, "Metro Ligero 1") // Default fallback
588| }
589| }
590| fileName == "ramal" -> Pair(R.drawable.ramal, "Ramal")
591| fileName == "escaleras-mecanicas" -> Pair(R.drawable.escaleras_mecanicas, "Escaleras Mecánicas")
