 // Custom TopBar con diseño mejorado
 Column(
 modifier = Modifier
 .fillMaxWidth()
 .background(Color(0xFF1976D2))
 .statusBarsPadding()
 .padding(start = 16.dp, end = 16.dp, top = 16.dp, bottom = 16.dp)
 ) {
 Text(
 text = "ESTADO DEL SERVICIO",
 color = Color.White.copy(alpha = 0.8f),
 fontSize = 12.sp,
 fontWeight = FontWeight.Normal
 )
 Text(
 text = "Metro Madrid",
