) {
 var expanded by remember { mutableStateOf(false) }
 val hasExpandableContent = estacion.correspondencias.isNotEmpty() || estacion.incidencias_especificas.isNotEmpty()

 Row(
 modifier = modifier
 .fillMaxWidth()
 .padding(horizontal = 16.dp),
