476|// Función para obtener el texto del avatar de la línea
477|fun getLineaAvatarText(nombre: String): String {
478| return when {
479| nombre.startsWith("linea-") -> {
480| // Extraer solo el número de la línea
481| val partes = nombre.removePrefix("linea-").split("-")
482| partes.firstOrNull()?.uppercase() ?: ""
483| }
484| nombre.startsWith("ml") -> nombre.uppercase()
485| nombre == "ramal" -> "R"
486| else -> nombre.take(2).uppercase()
487| }
488|}
489|
490|// Función para obtener el color de cada línea
491|fun getLineaColor(nombre: String): Color {
492| return when {
493| nombre.startsWith("linea-6") -> Color(0xFF808285) // Gris (para linea-6 y linea-6-circular)
494| nombre.startsWith("linea-12") -> Color(0xFFA49A00) // Amarillo oscuro (para linea-12 y linea-12-metrosur)
495| nombre == "linea-1" -> Color(0xFF00A9E0) // Celeste
496| nombre == "linea-2" -> Color(0xFFED1C24) // Rojo
497| nombre == "linea-3" -> Color(0xFFFFC000) // Amarillo
498| nombre == "linea-4" -> Color(0xFF9B3888) // Morado
499| nombre == "linea-5" -> Color(0xFF7FBF3F) // Verde claro
500| nombre == "linea-7" -> Color(0xFFFF6600) // Naranja
501| nombre == "linea-8" -> Color(0xFFE5007E) // Rosa
502| nombre == "linea-9" -> Color(0xFF9B3888) // Morado oscuro
503| nombre == "linea-10" -> Color(0xFF003F87) // Azul oscuro
504| nombre == "linea-11" -> Color(0xFF006633) // Verde oscuro
505| nombre == "ramal" -> Color(0xFF1976D2) // Azul
506| else -> Color(0xFF1976D2) // Azul por defecto
507| }
508|}
