664| modifier: Modifier,
665| colorLinea: Color
666|) {
667| var expanded by remember { mutableStateOf(false) }
668| val hasExpandableContent = estacion.correspondencias.isNotEmpty() || estacion.incidencias_especificas.isNotEmpty()
669|
670| Row(
