705| Row(
706| modifier = Modifier
707| .fillMaxWidth()
708| .padding(16.dp),
709| horizontalArrangement = Arrangement.SpaceBetween,
710| verticalAlignment = Alignment.CenterVertically
711| ) {
712| Row(
713| verticalAlignment = Alignment.CenterVertically,
714| modifier = Modifier.weight(1f)
715| ) {
716| if (estacion.tiene_incidencias) {
717| Icon(
718| imageVector = Icons.Default.Warning,
719| contentDescription = "Incidencias",
720| tint = Color(0xFFD32F2F),
721| modifier = Modifier.size(20.dp)
722| )
723| Spacer(modifier = Modifier.width(8.dp))
724| }
725|
726| Text(
727| text = estacion.nombre,
728| fontSize = 16.sp,
729| fontWeight = FontWeight.SemiBold,
730| color = Color.Black
