840|// Componente para badges de correspondencias
841|@Composable
842|fun CorrespondenciaBadge(svgUrl: String, isLarge: Boolean = false) {
843| val lineaName = svgUrl.substringAfterLast("/").removeSuffix(".svg")
844| val badgeColor = when {
845| lineaName.startsWith("linea-") -> getLineaColor(lineaName)
846| lineaName.startsWith("ml") -> Color(0xFF4CAF50)
847| lineaName.contains("c1") || lineaName.contains("C1") -> Color(0xFF808080)
848| lineaName.contains("c2") || lineaName.contains("C2") -> Color(0xFF808080)
849| else -> Color(0xFF1976D2)
850| }
851| 
852| val badgeText = when {
853| lineaName.startsWith("linea-") -> {
854| // Extraer solo el número de la línea (sin sufijos como -circular o -metrosur)
855| val partes = lineaName.removePrefix("linea-").split("-")
856| partes.firstOrNull()?.uppercase() ?: ""
857| }
858| lineaName.contains("c1", ignoreCase = true) -> "C1"
859| lineaName.contains("c2", ignoreCase = true) -> "C2"
860| lineaName.contains("c3", ignoreCase = true) -> "C3"
861| lineaName.contains("c4", ignoreCase = true) -> "C4"
862| lineaName.startsWith("ml") -> lineaName.uppercase()
863| lineaName == "ramal" -> "R"
864| else -> lineaName.take(2).uppercase()
865| }
866| 
867| val size = if (isLarge) 36.dp else 28.dp
868| val fontSize = if (isLarge) 14.sp else 11.sp
869| 
870| Box(
871| modifier = Modifier
872| .size(size)
873| .background(badgeColor, shape = RoundedCornerShape(50)),
874| contentAlignment = Alignment.Center
875| ) {
876| Text(
877| text = badgeText,
878| color = Color.White,
879| fontSize = fontSize,
880| fontWeight = FontWeight.Bold
881| )
882| }
883|}
884|
885|@Composable
886|fun formatLineaName(nombre: String): String {
887| return when {
888| nombre == "linea-6-circular" -> "Línea 6-CIRCULAR"
889| nombre == "linea-12-metrosur" -> "Línea 12-METROSUR"
890| nombre.startsWith("linea-") -> {
891| val numero = nombre.removePrefix("linea-")
892| "Línea ${numero.uppercase()}"
893| }
894| nombre.startsWith("ml") -> "Metro Ligero ${nombre.removePrefix("ml").uppercase()}"
895| nombre == "ramal" -> "Ramal"
896| else -> nombre.replaceFirstChar { it.uppercase() }
897| }
898|}
899|
900|fun getImageDrawableResource(svgUrl: String): Pair<Int, String> {
901| // Extract filename from URL
902| val fileName = svgUrl.substringAfterLast("/").removeSuffix(".svg")
903| 
904| return when {
905| fileName.startsWith("linea-") -> {
906| val numero = fileName.removePrefix("linea-")
907| when (numero) {
908| "1" -> Pair(R.drawable.linea_1, "Línea 1")
909| "2" -> Pair(R.drawable.linea_2, "Línea 2")
910| "3" -> Pair(R.drawable.linea_3, "Línea 3")
911| "4" -> Pair(R.drawable.linea_4, "Línea 4")
912| "5" -> Pair(R.drawable.linea_5, "Línea 5")
913| "6" -> Pair(R.drawable.linea_6_circular, "Línea 6 Circular")
914| "7" -> Pair(R.drawable.linea_7, "Línea 7")
915| "8" -> Pair(R.drawable.linea_8, "Línea 8")
916| "9" -> Pair(R.drawable.linea_9, "Línea 9")
917| "10" -> Pair(R.drawable.linea_10, "Línea 10")
918| "11" -> Pair(R.drawable.linea_11, "Línea 11")
919| "12" -> Pair(R.drawable.linea_12_metrosur, "Línea 12 MetroSur")
920| else -> Pair(R.drawable.linea_1, "Línea 1") // Default fallback
921| }
922| }
923| fileName.startsWith("ml") -> {
924| val numero = fileName.removePrefix("ml")
925| when (numero) {
926| "1" -> Pair(R.drawable.ml1, "Metro Ligero 1")
927| "2" -> Pair(R.drawable.ml2, "Metro Ligero 2")
928| "3" -> Pair(R.drawable.ml3, "Metro Ligero 3")
929| else -> Pair(R.drawable.ml1, "Metro Ligero 1") // Default fallback
930| }
931| }
932| fileName == "ramal" -> Pair(R.drawable.ramal, "Ramal")
933| fileName == "escaleras-mecanicas" -> Pair(R.drawable.escaleras_mecanicas, "Escaleras Mecánicas")
934| fileName == "ascensores" -> Pair(R.drawable.ascensores, "Ascensores")
935| fileName == "pasillos-rodantes" -> Pair(R.drawable.pasillos_rodantes, "Pasillos Rodantes")
936| else -> Pair(R.drawable.linea_1, "Línea 1") // Default fallback
937| }
938|}
