510|@OptIn(ExperimentalMaterial3Api::class)
511|@Composable
512|fun EstacionesScreen(
513| linea: Linea,
514| onBackClick: () -> Unit
515|) {
516| var searchQuery by remember { mutableStateOf("") }
517| var showOnlyIncidencias by remember { mutableStateOf(false) }
518|
519| val filteredEstaciones = remember(searchQuery, showOnlyIncidencias) {
520| derivedStateOf {
521| linea.estaciones.filter { estacion ->
522| val matchesSearch = estacion.nombre.contains(searchQuery, ignoreCase = true)
523| val matchesFilter = !showOnlyIncidencias || estacion.tiene_incidencias
524| matchesSearch && matchesFilter
525| }
526| }
527| }
528| 
529| val colorLinea = getLineaColor(linea.nombre)
530|
531| Scaffold(
532| topBar = {
533| // Custom TopBar con diseño mejorado para vista de estación
534| Column(
535| modifier = Modifier
536| .fillMaxWidth()
537| .background(colorLinea)
538| .statusBarsPadding()
539| ) {
540| // Header con botón de volver e info
541| Row(
542| modifier = Modifier
543| .fillMaxWidth()
544| .padding(start = 4.dp, end = 16.dp, top = 8.dp),
545| horizontalArrangement = Arrangement.SpaceBetween,
546| verticalAlignment = Alignment.CenterVertically
547| ) {
548| IconButton(onClick = onBackClick) {
549| Icon(
550| imageVector = Icons.AutoMirrored.Filled.ArrowBack,
551| contentDescription = "Volver",
552| tint = Color.White,
553| modifier = Modifier.size(28.dp)
554| )
555| }
556| 
557| IconButton(onClick = { /* Info */ }) {
558| Icon(
559| imageVector = Icons.Default.Info,
560| contentDescription = "Información",
561| tint = Color.White,
562| modifier = Modifier.size(24.dp)
563| )
564| }
565| }
566| 
567| // Título y subtítulo
568| Column(
569| modifier = Modifier
570| .fillMaxWidth()
571| .padding(start = 16.dp, end = 16.dp, bottom = 16.dp)
572| ) {
573| Text(
574| text = "ESTACIONES",
575| color = Color.White.copy(alpha = 0.85f),
576| fontSize = 12.sp,
577| fontWeight = FontWeight.Normal,
578| letterSpacing = 0.5.sp
579| )
580| Row(
581| verticalAlignment = Alignment.CenterVertically,
582| modifier = Modifier.padding(top = 4.dp)
583| ) {
584| // Badge con el número de la línea
585| Box(
586| modifier = Modifier
587| .size(40.dp)
588| .background(
589| color = Color.White.copy(alpha = 0.2f),
590| shape = RoundedCornerShape(8.dp)
591| ),
592| contentAlignment = Alignment.Center
593| ) {
594| Text(
595| text = getLineaAvatarText(linea.nombre),
596| color = Color.White,
597| fontSize = 18.sp,
598| fontWeight = FontWeight.Bold
599| )
600| }
601| 
602| Spacer(modifier = Modifier.width(12.dp))
603| 
604| Text(
605| text = formatLineaName(linea.nombre),
606| color = Color.White,
607| fontSize = 28.sp,
608| fontWeight = FontWeight.Bold
609| )
610| }
611| 
612| // Contador de estaciones
613| Text(
614| text = "${linea.estaciones.size} estaciones",
615| color = Color.White.copy(alpha = 0.85f),
616| fontSize = 14.sp,
617| fontWeight = FontWeight.Normal,
618| modifier = Modifier.padding(top = 8.dp)
619| )
620| }
621| }
622| }
623| ) { paddingValues ->
624| Column(
625| modifier = Modifier
626| .fillMaxSize()
627| .background(Color(0xFFF5F5F5))
628| ) {
629| // Search and Filter Section
630| Column(
631| modifier = Modifier
632| .fillMaxWidth()
633| .background(Color.White)
634| .padding(top = paddingValues.calculateTopPadding())
635| .padding(16.dp)
636| ) {
637| // Search field con icono
638| TextField(
639| value = searchQuery,
640| onValueChange = { searchQuery = it },
641| modifier = Modifier
642| .fillMaxWidth(),
643| placeholder = { 
644| Text(
645| text = "Buscar estación...",
646| color = Color.Gray
647| ) 
648| },
649| leadingIcon = {
650| Icon(
651| imageVector = Icons.Default.Search,
652| contentDescription = "Buscar",
653| tint = Color.Gray
654| )
655| },
656| singleLine = true,
657| shape = RoundedCornerShape(12.dp),
658| colors = TextFieldDefaults.colors(
659| focusedContainerColor = Color(0xFFF5F5F5),
660| unfocusedContainerColor = Color(0xFFF5F5F5),
661| focusedIndicatorColor = Color.Transparent,
662| unfocusedIndicatorColor = Color.Transparent
663| )
664| )
665|
666| Spacer(modifier = Modifier.height(16.dp))
667|
668| Row(
669| modifier = Modifier.fillMaxWidth(),
670| horizontalArrangement = Arrangement.SpaceBetween,
671| verticalAlignment = Alignment.CenterVertically
672| ) {
673| Text(
674| text = "Mostrar solo estaciones con incidencias",
675| fontSize = 14.sp,
676| color = Color(0xFF333333)
677| )
678| Switch(
679| checked = showOnlyIncidencias,
680| onCheckedChange = { showOnlyIncidencias = it }
681| )
682| }
683| }
684|
685| // Stations List con línea vertical
686| Box(
687| modifier = Modifier
688| .fillMaxSize()
689| .padding(top = 16.dp)
690| ) {
691| // Línea vertical de la línea de metro
692| Box(
693| modifier = Modifier
694| .width(4.dp)
695| .fillMaxSize()
696| .padding(start = 32.dp)
697| .background(colorLinea.copy(alpha = 0.3f))
698| )
699| 
700| LazyColumn(
701| modifier = Modifier.fillMaxSize(),
702| contentPadding = androidx.compose.foundation.layout.PaddingValues(
703| bottom = paddingValues.calculateBottomPadding()
704| ),
705| verticalArrangement = Arrangement.spacedBy(8.dp)
706| ) {
