 val lineaNombre = backStackEntry.arguments?.getString("lineaNombre")
 val linea = metroData.lineas.find { it.nombre == lineaNombre }

 if (linea != null) {
 EstacionesScreen(
 linea = linea,
 onBackClick = { navController.popBackStack() }
 )
 }
 }
 }
 }
}

